const s = require('fs').readFileSync('/dev/stdin', 'utf8').trim();

let count = 0;
let i = 0;
while (i < s.length) {
    let j = i;
    while (j < s.length && s[j] === s[i]) j++;
    let runLength = j - i;
    if (runLength % 2 === 0) count++;
    i = j;
}

console.log(count);
